CREATE SCHEMA NLP;
CREATE COLUMN TABLE NLP.SCRIPT_FAMILY (SCRIPT_ID NVARCHAR(36) PRIMARY KEY, CANONICAL_CODE NVARCHAR(64) NOT NULL UNIQUE, NAME NVARCHAR(200) NOT NULL, FAMILY NVARCHAR(200), WRITING_DIRECTION NVARCHAR(16) DEFAULT 'unknown' NOT NULL, DECIPHERMENT_STATUS NVARCHAR(32) DEFAULT 'partial' NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.SOURCE_DOCUMENT (DOCUMENT_ID NVARCHAR(36) PRIMARY KEY, EXTERNAL_ID NVARCHAR(256), TITLE NCLOB, URI NCLOB, MEDIA_TYPE NVARCHAR(128), CHECKSUM_SHA256 NVARCHAR(64), CAPTURED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.INSCRIPTION (INSCRIPTION_ID NVARCHAR(36) PRIMARY KEY, DOCUMENT_ID NVARCHAR(36), SCRIPT_ID NVARCHAR(36) NOT NULL, SCHOLARLY_ID NVARCHAR(256), LANGUAGE_CODE NVARCHAR(64), TRANSLITERATION NCLOB, TRANSLATION NCLOB, CONFIDENCE DECIMAL(6,5), UNCERTAINTY NCLOB, PROVENANCE NCLOB, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.GLYPH_OBSERVATION (GLYPH_ID NVARCHAR(36) PRIMARY KEY, INSCRIPTION_ID NVARCHAR(36) NOT NULL, SEQUENCE_NO INTEGER NOT NULL, UNICODE_CODEPOINT NVARCHAR(32), GLYPH_LABEL NVARCHAR(128), BOUNDING_BOX NCLOB, IMAGE_URI NCLOB, RECOGNIZED_TEXT NCLOB, CONFIDENCE DECIMAL(6,5), DAMAGED TINYINT DEFAULT 0 NOT NULL, ALTERNATE_READINGS NCLOB, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(INSCRIPTION_ID,SEQUENCE_NO));
CREATE COLUMN TABLE NLP.READING (READING_ID NVARCHAR(36) PRIMARY KEY, INSCRIPTION_ID NVARCHAR(36) NOT NULL, READING_TEXT NCLOB NOT NULL, TRANSLITERATION NCLOB, NORMALIZED_TEXT NCLOB, CONFIDENCE DECIMAL(6,5), REVIEWER NVARCHAR(256), EVIDENCE NCLOB, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.TRANSLATION_CANDIDATE (CANDIDATE_ID NVARCHAR(36) PRIMARY KEY, READING_ID NVARCHAR(36) NOT NULL, TARGET_LANGUAGE NVARCHAR(32) NOT NULL, TRANSLATION NCLOB NOT NULL, MODEL_ID NVARCHAR(36), CONFIDENCE DECIMAL(6,5), RANK_NO INTEGER, EVIDENCE NCLOB, HUMAN_VERIFIED TINYINT DEFAULT 0 NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.MODEL_REGISTRY (MODEL_ID NVARCHAR(36) PRIMARY KEY, MODEL_NAME NVARCHAR(256) NOT NULL UNIQUE, ARCHITECTURE NVARCHAR(128), TASK NVARCHAR(128), PROVIDER NVARCHAR(256), LICENSE NVARCHAR(256), METADATA NCLOB, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE COLUMN TABLE NLP.MODEL_VERSION (MODEL_VERSION_ID NVARCHAR(36) PRIMARY KEY, MODEL_ID NVARCHAR(36) NOT NULL, VERSION NVARCHAR(128) NOT NULL, ARTIFACT_URI NCLOB, CHECKSUM_SHA256 NVARCHAR(64), PARAMETERS BIGINT, FRAMEWORK NVARCHAR(128), METRICS NCLOB, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(MODEL_ID,VERSION));
CREATE COLUMN TABLE NLP.INFERENCE_RUN (RUN_ID NVARCHAR(36) PRIMARY KEY, MODEL_VERSION_ID NVARCHAR(36), INSCRIPTION_ID NVARCHAR(36), OPERATION NVARCHAR(64) NOT NULL, INPUT_HASH NVARCHAR(64), OUTPUT NCLOB, LATENCY_MS DECIMAL(18,3), CONFIDENCE DECIMAL(6,5), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
